package br.edu.ifc.treinoecapacitacao.view;
import br.edu.ifc.treinoecapacitacao.App; import javafx.geometry.*; import javafx.scene.*; import javafx.scene.control.*; import javafx.scene.layout.*; import javafx.stage.Stage;
public class TelaHistorico { private Stage stage; public TelaHistorico(Stage stage){this.stage=stage;} public Scene criarCena(){Label titulo=new Label("Histórico");titulo.setId("tituloTreinamentos");ListView<String> lista=new ListView<String>(App.historico);lista.setPrefHeight(350);Button voltar=new Button("Voltar");voltar.setOnAction(e->{stage.setScene(new TelaDashboard(stage).criarCena());stage.setTitle("Painel - Treinamento e Capacitação");});VBox raiz=new VBox(12,titulo,new Label("Operações realizadas no sistema"),lista,voltar);raiz.setPadding(new Insets(25));raiz.setAlignment(Pos.TOP_CENTER);Scene scene=new Scene(raiz,700,500);scene.getStylesheets().add("/css/style.css");return scene;} }
